package com.himeros.trustsafety;import jakarta.persistence.*;import java.time.*;import java.util.*;@Entity@Table(name="reports")class Report{@Id private UUID id;@Column(name="reporter_id",nullable=false)private UUID reporter;@Column(name="reported_id",nullable=false)private UUID reported;@Column(nullable=false)private String reason;@Column(length=1000)private String details;@Enumerated(EnumType.STRING)@Column(nullable=false)private Status status;@Column(name="created_at",nullable=false)private Instant created;enum Status{OPEN,REVIEWING,CLOSED}protected Report(){}UUID id(){return id;}UUID reported(){return reported;}Instant created(){return created;}Report(UUID a,UUID b,String reason,String details){id=UUID.randomUUID();reporter=a;reported=b;this.reason=reason;this.details=details;status=Status.OPEN;created=Instant.now();}}
